const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json.query || item.json.body || item.json || {};

  const value_coin = data.value_coin !== undefined && data.value_coin !== '' ? String(data.value_coin) : '';
  const value_forwarded = data.value_forwarded_coin !== undefined && data.value_forwarded_coin !== '' ? String(data.value_forwarded_coin) : '';
  const txid_in = data.txid_in !== undefined && data.txid_in !== '' ? String(data.txid_in) : '';
  const txid_out = data.txid_out !== undefined && data.txid_out !== '' ? String(data.txid_out) : '';
  const status = data.status !== undefined && data.status !== '' ? String(data.status).toLowerCase() : '';
  const address_in = data.address_in || data.polygon_address_in || data.address || '';
  const currency = data.currency || data.coin || 'USDC';

  // Identificar si la operacion esta completada o en proceso
  const isCompleted = Boolean(
    (txid_out && txid_out !== 'null' && txid_out !== 'undefined' && txid_out !== '') ||
    ['paid', 'confirmed', 'forwarded', 'completed', 'done', 'success'].includes(status) ||
    (value_forwarded && Number(value_forwarded) > 0)
  );

  const event_type = isCompleted ? 'COMPLETED' : 'IN_PROGRESS';

  let telegram_text = '';
  let whatsapp_text = '';

  if (isCompleted) {
    const displayNet = value_forwarded || value_coin || '0';
    telegram_text = '🚀 *¡PAGO COMPLETADO EN CARD2CRYPTO!*\n\n' +
      '💵 *Monto Recibido:* $' + (value_coin || displayNet) + ' ' + currency + '\n' +
      '📥 *Monto Neto:* $' + displayNet + ' ' + currency + '\n' +
      '📊 *Estado:* ✅ Fondos transferidos a billetera\n\n' +
      '🆔 *TXID Payout:*\n`' + (txid_out || 'Confirmado en pasarela') + '`';

    whatsapp_text = '🚀 ¡PAGO COMPLETADO EN CARD2CRYPTO!\n\n' +
      '💵 Monto Recibido: $' + (value_coin || displayNet) + ' ' + currency + '\n' +
      '📥 Monto Neto: $' + displayNet + ' ' + currency + '\n' +
      '📊 Estado: ✅ Fondos transferidos a billetera\n' +
      '🆔 TXID Payout: ' + (txid_out || 'Confirmado');
  } else {
    telegram_text = '⏳ *¡PAGO EN PROCESO EN CARD2CRYPTO!*\n\n' +
      '💵 *Monto Detectado:* $' + (value_coin || 'Pendiente') + ' ' + currency + '\n' +
      '📊 *Estado:* 🟡 Transacción iniciada / Confirmando en red\n\n' +
      '🔗 *TXID Entrada:*\n`' + (txid_in || 'Procesando en pasarela...') + '`\n\n' +
      '📥 *Billetera Temporal:*\n`' + (address_in || 'No especificada') + '`';

    whatsapp_text = '⏳ ¡PAGO EN PROCESO EN CARD2CRYPTO!\n\n' +
      '💵 Monto Detectado: $' + (value_coin || 'Pendiente') + ' ' + currency + '\n' +
      '📊 Estado: 🟡 Transacción iniciada / Confirmando en red\n' +
      '🔗 TXID Entrada: ' + (txid_in || 'Procesando en pasarela...') + '\n' +
      '📥 Billetera: ' + (address_in || 'No especificada');
  }

  results.push({
    json: {
      ...data,
      event_type,
      is_completed: isCompleted,
      value_coin,
      value_forwarded,
      txid_in,
      txid_out,
      status,
      address_in,
      telegram_text,
      whatsapp_text
    }
  });
}

return results;
